package android.widget;import android.view.View;import android.content.Context;public class TextView extends View {private CharSequence text="",hint;public TextView(Context c){super(c);}public CharSequence getText(){return text;}public void setText(CharSequence s){text=s;}public void setText(int id){text=getResources().getString(id);}public CharSequence getHint(){return hint;}public void setHint(CharSequence s){hint=s;}public void setHint(int id){hint=getResources().getString(id);}}
